'''/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones. Purged issues are
 * gone from the table, so the floor they leave behind is folded in too.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const floor = getDb()
    .select({ value: projectNumberFloors.floor })
    .from(projectNumberFloors)
    .where(eq(projectNumberFloors.projectId, projectId))
    .get();
  return Math.max(row?.value ?? 0, floor?.value ?? 0) + 1;
}

/** Every archived issue of the org archived at or before `cutoff`, all projects. */
export async function listExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        isNotNull(issues.archivedAt),
        lte(issues.archivedAt, cutoff),
      ),
    )
    .orderBy(issues.archivedAt, issues.id)
    .all();

  return rows.map((row) => toIssue(row));
}

/**
 * Permanently removes one issue with its label links, and raises the
 * project's numbering floor to the issue's number so it is never reused.
 */
export async function purgeIssue(
  orgId: OrgId,
  issue: Issue,
): Promise<void> {
  const db = getDb();

  db.delete(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.issueId, issue.id),
      ),
    )
    .run();

  db.delete(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issue.id)))
    .run();

  db.insert(projectNumberFloors)
    .values({ orgId, projectId: issue.projectId, floor: issue.number })
    .onConflictDoUpdate({
      target: projectNumberFloors.projectId,
      set: {
        floor: sql`max(${projectNumberFloors.floor}, ${issue.number})`,
      },
    })
    .run();
}'''),
])
